var n := 0
for e in GameEventLog.entries:
	if str(e.get("text", "")).find("Advanced Firepower: Caladius Annihilator Grav-Tank re-rolls one") >= 0:
		n += 1
return n

var n := 0
for e in GameEventLog.entries:
	var t := str(e.get("text", ""))
	if t.find("Advanced Firepower") >= 0 and t.find("hit roll") >= 0:
		n += 1
return n

var panel = null
for n in tree.root.get_node("Main").find_children("*", "", true, false):
	if n.get("_tab_dice_button") != null:
		panel = n
		break
if panel == null:
	return "panel not found"
if panel.get("_tab_game_button") != null:
	panel._tab_game_button.emit_signal("pressed")
return true
